<?php	/**	* Fecha: 22/11/2013	* Descripción: Version 3.0 de menu Horizontal.	* Comentarios: Genera un menú vertical y el encabezado a partir de una serie de menus registrados	* en la base de datos.	**/	require_once('../CelaMen_u/CelaMen_u.php');	function GetMenu($Category, $CurrentOption, $CurrentCategory, $Level, $LevelTag, $SessionGroup, $IndexCategory){		global $Connection;		$SideBar = '';		$Query =    sprintf('SELECT								 cu.`id`, cu.`Nombre`, cu.`Descripci_on`, cu.`Referencia`, cu.`TipoDeElemento`, cu.`Prioridad`,								 c.`Nombre` as Icono							 FROM CelaMen_u cu								 INNER JOIN CelaIcono c ON ( cu.`Icono` = c.`id`  )							 WHERE								 cu.`Categor_ia` = %s AND								 cu.`Orientaci_on` = %s AND								 cu.`id` != %s AND								 cu.`id` IN	(SELECT												c1.Tupla											 FROM											    CelaPrivilegios c1											 WHERE											    c1.TuplaAcceso = %s AND											    c1.Origen = %s										    )							 ORDER BY								 cu.`Prioridad`;',					GetSQLValueString($Category, 'int'),					GetSQLValueString(1, 'int'),					GetSQLValueString($Category, 'int'),					GetSQLValueString($SessionGroup, 'int'),					GetSQLValueString(1, 'int')				);		/**		print '<pre>';		print $Query;		print '</pre>';		/**/		//		//' . ($CurrentOption == $Record['id'] ? 'active':'') . '		$Result = $Connection -> query($Query);		while($Record = $Result -> fetch_assoc()){			$SubMenu = (isset($IndexCategory[($Level+1)]) && $Record['id'] == $IndexCategory[($Level+1)] ? true:false);			switch($Record['TipoDeElemento']){				case 1:				/*	$SideBar .= '   <li class="nav-item">										 <a class="nav-link has-collapse collapsed" href="' . str_replace('.php', '', $Record['Referencia']) . '" data-bs-toggle="collapse" data-bs-target="#side-dropdown'.$Record['id'].'" aria-expanded="' . ($Record['id'] == $CurrentCategory || $SubMenu === true ? 'true':'false') . '" aria-controls="side-dropdown"><i class="' . $Record['Icono'] . '"></i><span>' . $Record['Nombre'] . '</span></a>									<div class="collapse" id="side-dropdown'.$Record['id'].'" data-bs-parent="#side-dropdown'.$CurrentCategory.'">										<ul class="nav">';					$SideBar .= GetMenu($Record['id'], $CurrentOption, $CurrentCategory, ($Level+1), $LevelTag, $SessionGroup, $IndexCategory);					$SideBar .=       '	</ul>									</div>								</li>';*/					$SideBar .= '' .					'<div class="menu-item has-sub ' . ($Record['id'] == $CurrentCategory || $SubMenu === true ? 'expand active':'') . '">						<a href="' . str_replace('.php', '', $Record['Referencia']) . '" class="menu-link">							<div class="menu-icon">								<i class="' . $Record['Icono'] . '"></i>							</div>							<div class="menu-text">' . $Record['Nombre'] . '</div>							<div class="menu-caret"></div>						</a>						<div class="menu-submenu">';					$SideBar .=  GetMenu($Record['id'], $CurrentOption, $CurrentCategory, ($Level+1), $LevelTag, $SessionGroup, $Category);					$SideBar .= '' .						'</div>					</div>';					break;				case 2:					$SideBar .= '' .						'<div class="menu-item ' . ($Record['id'] == $CurrentOption || $SubMenu === true ? 'active':'') . '">							<a href="' . str_replace('.php', '', $Record['Referencia']) . '?' . EncodeThis('MenuId='.$Record['id']) . '" class="menu-link" title="' . $Record['Descripci_on'] . '">								<div class="menu-icon">									<i class="' . $Record['Icono'] . '"></i>								</div>								<div class="menu-text">' . $Record['Nombre'] . '</div>							</a>						</div>';					break;				case 4:					$SideBar .= '' .						'<div class="menu-item ' . ($Record['id'] == $CurrentOption || $SubMenu === true ? 'active':'') . '">							<a target="_blank" href="' . str_replace('.php', '', $Record['Referencia']) . '?' . EncodeThis('MenuId='.$Record['id']) . '" class="menu-link" title="' . $Record['Descripci_on'] . '">								<div class="menu-icon">									<i class="' . $Record['Icono'] . '"></i>								</div>								<div class="menu-text">' . $Record['Nombre'] . '</div>							</a>						</div>';					break;				case 5:					$SideBar .= '' .						'<div class="menu-item ' . ($Record['id'] == $CurrentOption || $SubMenu === true ? 'active':'') . '">							<a target="_blank" href="CelaRepositorio.php?' . EncodeThis('Key='.$Record['Referencia'] . '&Action=VistaPrevia&MenuId='.$Record['id']) . '" class="menu-link" title="' . $Record['Descripci_on'] . '">								<div class="menu-icon">									<i class="' . $Record['Icono'] . '"></i>								</div>								<div class="menu-text">' . $Record['Nombre'] . '</div>							</a>						</div>';					break;			}		}		return $SideBar;	}	$CurrentCategory =  GetValue(							sprintf('SELECT `Categor_ia` FROM CelaMen_u WHERE `id` = %s;',								GetSQLValueString($CurrentMenu, 'varchar')							),							'Categor_ia'						);	/**/	$Category = array();	if($CurrentMenu != ''){		$Category = array_reverse(CelaMen_uObtenCategor_iaPadre($CurrentMenu));	}	/**	print_r($Category);	/**/	$LevelTag   = array('', 'nav-second-level', 'nav-third-level', 'nav-fourth-level', 'nav-fifth-level');	$IconBgTag  = array('bg-danger', 'bg-info', 'bg-success', 'bg-warning', 'bg-primary', 'bg-orange', 'bg-violet','bg-facebook', 'bg-twitter', 'bg-google-plus','bg-danger', 'bg-info', 'bg-success', 'bg-warning', 'bg-primary', 'bg-orange', 'bg-violet','bg-facebook', 'bg-twitter', 'bg-google-plus');	$IconBg     = 0;	$MenuQuery =    sprintf('	SELECT									cu.`id`, cu.`Nombre`, cu.`Descripci_on`, cu.`Referencia`, cu.`TipoDeElemento`, cu.`Prioridad`,									c.`Nombre` as Icono								FROM CelaMen_u cu									INNER JOIN CelaIcono c ON ( cu.`Icono` = c.`id`  )								WHERE									cu.`Orientaci_on` = %s AND									cu.`Categor_ia`   = cu.`id`AND									cu.`id` IN	(SELECT													c1.Tupla												 FROM												    CelaPrivilegios c1												 WHERE												    c1.TuplaAcceso = %s AND												    c1.Origen = %s											    )								ORDER BY									cu.`Prioridad` ASC;',						GetSQLValueString(1, 'int'),						GetSQLValueString($SessionGroup, 'int'),						GetSQLValueString(1, 'int')					);	/**	print '<pre>';	print $MenuQuery;	print '</pre>';	/**/	$Result = $Connection -> query($MenuQuery);	$SideBar = '';	$Level = -1;	while($Record = $Result -> fetch_assoc()){		$SubMenu = (isset($Category[($Level+1)]) && $Record['id'] == $Category[($Level+1)] ? true:false);		switch($Record['TipoDeElemento']){			case 1: /*Categoria principal*/				$SideBar .= '' .					'<div class="menu-item has-sub ' . ($Record['id'] == $CurrentCategory || $SubMenu === true ? 'expand active':'') . '">						<a href="' . str_replace('.php', '', $Record['Referencia']) . '" class="menu-link">							<div class="menu-icon">								<i class="' . $Record['Icono'] . '"></i>							</div>							<div class="menu-text">' . $Record['Nombre'] . '</div>							<div class="menu-caret"></div>						</a>						<div class="menu-submenu">';				$SideBar .=  GetMenu($Record['id'], $CurrentMenu, $CurrentCategory, ($Level+1), $LevelTag, $SessionGroup, $Category);				$SideBar .= '' .						'</div>					</div>';				break;			case 2:/*Elemento de menú*/				$SideBar .= '' .					'<div class="menu-item ' . ($CurrentMenu == $Record['id'] ? 'active':'') . '">						<a href="' . str_replace('.php', '', $Record['Referencia']) . '?' . EncodeThis('MenuId='.$Record['id']) . '" class="menu-link" title="' . $Record['Descripci_on'] . '">							<div class="menu-icon">								<i class="' . $Record['Icono'] . '"></i>							</div>							<div class="menu-text">' . $Record['Nombre'] . '</div>						</a>					</div>';				break;			case 4: /*enlace externo*/				$SideBar .= '' .					'<div class="menu-item ' . ($CurrentMenu == $Record['id'] ? 'active':'') . '">						<a target="_blank" href="' . str_replace('.php', '', $Record['Referencia']) . '?' . EncodeThis('MenuId='.$Record['id']) . '" class="menu-link" title="' . $Record['Descripci_on'] . '">							<div class="menu-icon">								<i class="' . $Record['Icono'] . '"></i>							</div>							<div class="menu-text">' . $Record['Nombre'] . '</div>						</a>					</div>';				break;			case 5: /*Documento*/				$SideBar .= '' .					'<div class="menu-item ' . ($CurrentMenu == $Record['id'] ? 'active':'') . '">						<a target="_blank" href="CelaRepositorio.php?' . EncodeThis('Key='.$Record['Referencia'] . '&Action=VistaPrevia&MenuId='.$Record['id']) . '" class="menu-link" title="' . $Record['Descripci_on'] . '">							<div class="menu-icon">								<i class="' . $Record['Icono'] . '"></i>							</div>							<div class="menu-text">' . $Record['Nombre'] . '</div>						</a>					</div>';				break;		}		$IconBg++;	}?><?php /*<nav id="nav-scroll" class="side-nav left-nav navbar-expand-lg nav bg-white">	<button class="navbar-toggler collapsed" type="button" data-bs-toggle="collapse" data-bs-target="#navbar-toggle" aria-controls="navbar-toggle" aria-expanded="false" aria-label="Toggle navigation">		<span class="icon-bar top-bar"></span>		<span class="icon-bar middle-bar"></span>		<span class="icon-bar bottom-bar"></span>	</button><!-- / navbar-toggler -->	<div class="collapse navbar-collapse" id="navbar-toggle">		<ul class="pl-0" id="main-collapse">			<li class="sidenav-logo" style="text-align: center;">		<?php//	        $Logo = GetValue(//				sprintf('SELECT Valor FROM CelaConfiguraci_on WHERE Nombre = %s;',//					GetSQLValueString('Logotipo', 'varchar')//				),//				'Valor'//			);			$Logo = $GlobalConfig['Logotipo'];			if($Logo != 'NULL' && $Logo != '') {		?>				<a href="Escritorio">					<img style="height: 90px !important;" alt="" class="img-polaroid" src="<?= $Logo; ?>" class="img-responsive"/>				</a>		<?php			}		?>			</li>			<?= $SideBar; ?>		</ul><!-- / main-collapse -->	</div><!-- / collapse --></nav><!-- / nav-scroll --><!-- / side-nav -->*/ ?><div id="sidebar" class=